const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const money=value=>new Intl.NumberFormat('da-DK',{style:'currency',currency:'DKK'}).format(value/100);
export async function editProductPrices(product,api,onSaved=()=>{}){
 const dialog=el('dialog');dialog.className='product-price-dialog';const title=el('h2',product.name),close=el('button','Luk'),body=el('div','Indlæser priser…');close.type='button';close.onclick=()=>dialog.close();dialog.append(close,title,body);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();
 const endpoint=`/api/admin/products/${encodeURIComponent(product.id)}/prices`;
 try{let data=await(await api(endpoint)).json();if(!dialog.isConnected)return;
 const selector=el('select');selector.setAttribute('aria-label','Vis priser og indkøbspris for variant');for(const variant of data.variants){const option=el('option',variant.label);option.value=variant.sku;selector.append(option);}
 const note=el('p','Varepriser pr. stk. Tryk, opstart og fragt beregnes separat. Vælg, om prisen skal gælde alle varianter eller kun den valgte farve og størrelse. Prisen bevares ved PF-opdateringer.');
 const content=el('div'),feedback=el('p');feedback.setAttribute('role','status');body.replaceChildren(note,el('p','En tidsbegrænset pris gælder straks og vender automatisk tilbage ved udløb. Den gælder alle kunder, der køber den valgte vare i perioden.'),selector,content,feedback);
 function draw(){const v=data.variants.find(v=>v.sku===selector.value);content.replaceChildren();
 content.append(el('p',`${v.custom?'Manuelle salgspriser':'Automatiske salgspriser'} · PF-priser opdateret: ${data.updatedAt?new Date(data.updatedAt).toLocaleDateString('da-DK'):'Ikke tilgængelige'}`));
 if(v.expiresAt)content.append(el('p',`Midlertidig pris indtil ${new Date(v.expiresAt).toLocaleString('da-DK')}. Derefter gælder den tidligere pris igen.`));
 if(!v.sale.available){content.append(el('p',v.sale.message));}
 const costs=el('p',v.costTiers.length?`Købspriser (${v.currency}, ekskl. moms): ${v.costTiers.map(t=>`${t.min}+ stk.: ${v.currency==='DKK'?money(t.unitExVat):(t.unitExVat/100).toFixed(2)}`).join(' · ')}`:'Købspriser er ikke tilgængelige.');content.append(costs);
 const form=el('form'),table=el('table'),head=el('tr');for(const label of ['Antal fra','Køb ekskl. moms','Salg ekskl. moms','Salg inkl. moms'])head.append(el('th',label));const thead=el('thead');thead.append(head);table.append(thead);const tbody=el('tbody'),inputs=[];
 for(const row of v.sale.tiers){const tr=el('tr'),cost=[...v.costTiers].sort((a,b)=>b.min-a.min).find(t=>t.min<=row.min),cell=el('td'),input=el('input'),incl=el('td'),gross=el('input');input.type='number';input.min='0.01';input.max='1000000';input.step='0.01';input.required=true;input.value=(row.unitExVat/100).toFixed(2);input.setAttribute('aria-label',`Salgspris ekskl. moms fra ${row.min} stk.`);gross.type='number';gross.min='0.01';gross.max='1250000';gross.step='0.01';gross.required=true;gross.value=(row.unitIncVat/100).toFixed(2);gross.setAttribute('aria-label',`Salgspris inkl. moms fra ${row.min} stk.`);input.oninput=()=>{const cents=Math.round(Number(input.value)*100);gross.value=input.value!==''&&Number.isFinite(cents)?((cents+Math.round(cents*.25))/100).toFixed(2):'';};gross.oninput=()=>{input.value=gross.value!==''?(Math.round(Number(gross.value)*100/1.25)/100).toFixed(2):'';};gross.onchange=()=>{if(input.value!=='')input.oninput();};cell.append(input);incl.append(gross);tr.append(el('td',`${row.min}+`),el('td',cost?money(cost.unitExVat):'—'),cell,incl);tbody.append(tr);inputs.push({min:row.min,input});}
 table.append(tbody);form.append(table);const durationLabel=el('label','Prisens varighed'),duration=el('select');for(const [value,label] of [[0,'Permanent'],[30,'30 minutter'],[60,'60 minutter']]){const item=el('option',label);item.value=String(value);duration.append(item);}durationLabel.append(duration);form.append(durationLabel);const variantSave=el('button','Gem kun denne variant');variantSave.type='submit';variantSave.disabled=!v.sale.available;const save=el('button','Gem for alle varianter'),reset=el('button','Brug automatiske priser for alle');save.type='submit';save.disabled=!v.sale.available;reset.type='button';reset.disabled=!data.variants.some(variant=>variant.custom);const actions=el('div');actions.className='price-actions';actions.append(save,variantSave,reset);form.append(actions);content.append(form);
 async function persist(tiers,scope='product'){const durationMinutes=tiers===null?0:Number(duration.value);variantSave.disabled=true;save.disabled=true;reset.disabled=true;feedback.textContent='Gemmer…';try{data=await(await api(endpoint,'POST',{sku:v.sku,tiers,scope,durationMinutes})).json();onSaved(data.summary);draw();feedback.textContent=tiers===null?'Automatiske priser er gendannet for alle varianter.':`Priserne er gemt ${scope==='variant'?'kun for '+v.label:'for alle produktets varianter'}.${durationMinutes?' Gælder i '+durationMinutes+' minutter, derefter gendannes den tidligere pris.':''} Genindlæs webshoppen for at se ændringen.`;}catch(error){feedback.textContent=error.message;variantSave.disabled=!v.sale.available;save.disabled=!v.sale.available;reset.disabled=!data.variants.some(variant=>variant.custom);}}
 form.onsubmit=event=>{event.preventDefault();persist(inputs.map(({min,input})=>({min,unitExVat:Math.round(Number(input.value)*100)})),event.submitter===variantSave?'variant':'product');};reset.onclick=()=>persist(null);
 }
 selector.onchange=()=>{feedback.textContent='';draw();};draw();
 }catch(error){body.textContent=error.message;}
}
